const t = $('When Executed by Another Workflow').item.json;
const cfg = $json;
const clean = v => (v === undefined || v === null) ? null : (String(v).trim() || null);
const parseObj = v => { if (!v) return {}; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return {}; } } return v; };
const session_key = clean(t.session_key);
const message = clean(t.message);
if (!session_key) throw new Error('Entry: falta session_key');
if (!message) throw new Error('Entry: falta message');
const canal = clean(t.canal) || (session_key.includes(':') ? session_key.split(':')[0] : 'webchat');
const from = parseObj(t.from);
return [{ json: {
  session_key, message, canal,
  tenant: clean(t.tenant) || '__TENANT_ID__',
  from_phone: clean(from.phone), from_name: clean(from.name),
  reply_to: parseObj(t.reply_to),
  client_message_id: clean(t.client_message_id),
  booking_base_url: cfg.booking_base_url, directus_base_url: cfg.directus_base_url,
  tenant_timezone: cfg.tenant_timezone,
  rl_window_ms: cfg.rl_window_ms, rl_max: cfg.rl_max,
  privacy_intro: '¡Hola! Soy Lucía, la asistente virtual de ' + cfg.tenant_display_name
    + '. Gracias por escribirnos \uD83D\uDE0A\n\n'
    + 'Queremos informarte que guardamos tus datos solo para gestionar tu cita.',
  privacy_policy_url: cfg.privacy_policy_url,
  privacy_button_label: cfg.privacy_button_label,
  // 'v1' (router determinista) o 'v2' (agente con tools). Ver n8n/prompts/lucia-v2.md.
  core_version: (cfg.core_version || 'v1').toString().trim().toLowerCase(),
} }];

const inp = $('Code · Validar entrada').item.json;
// Por nombre y no por $json: entre Cargar sesión y este nodo va el resolutor de
// contacto, y $json es SU salida.
const r = $('HTTP · Cargar sesión').item.json ?? {};

// Quién es. Lo resuelve 17 por teléfono -- el MISMO resolutor que usan las tools,
// así que no pueden discrepar sobre quién es el contacto.
//
// Antes se esperaba que el Core devolviera `contact_id`, y NO lo hacía: dentro de
// un agente, `$(tool).first().json` no da el JSON del sub-workflow, así que tanto
// `contact_id` como `contact_phone` llegaban siempre a null. Consecuencia: la
// sesión se quedaba SIN contacto para siempre -- bandeja sin nombre, mensajes sin
// contacto, y el panel de citas de la interfaz sin activarse nunca.
// Si la sesión YA tenía contacto, `17` ni se ejecuta y $json es la respuesta de
// Cargar sesión -- que no trae `contact_id` en la raíz, así que esto queda a null
// y manda `row.contact_id`. Resolverlo en cada turno costaba SEIS ejecuciones de
// n8n (17 -> 07/16 -> 06 + 08 + 09) para averiguar algo que la sesión ya sabía.
let _contacto_resuelto = null;
try {
  const res = $json ?? {};
  _contacto_resuelto = res.contact_id || null;
} catch (e) {
  _contacto_resuelto = null;
}
const code = r.statusCode ?? 0;
const body = (r.body ?? r) || {};
if (code >= 300 || (body && body.errors)) {
  throw new Error('Directus /items/conversation_sessions ' + code + ': ' + JSON.stringify(body.errors || body));
}
const row = Array.isArray(body.data) && body.data.length ? body.data[0] : null;

// --- relevo humano ---------------------------------------------------------
// `modo` lo escribe el gestor desde Directus; Entry solo lo LEE. Si Entry lo
// escribiera, cada turno lo devolvería a 'auto' y el relevo duraría un mensaje.
// OJO: `HTTP · Cargar sesión` pide una lista EXPLÍCITA de campos. Un campo nuevo
// de conversation_sessions que no se añada ahí llega como undefined y esto cae al
// valor por defecto sin dar ningún error -- que es exactamente como `modo` se
// quedó siempre en 'auto' y el relevo no se activaba nunca.
const _modo = (row && row.modo) ? String(row.modo) : 'auto';
// El relevo es de WhatsApp. En webchat no hay forma de empujarle nada a un
// navegador que ya cerró la pestaña, así que callar a Lucía ahí no deja al
// cliente "esperando a una persona": lo deja mirando un chat muerto. Mejor que
// siga respondiendo ella.
const _relevo = _modo === 'humano' && inp.canal === 'whatsapp';

// Fin de la ventana de 24h de WhatsApp: se reinicia con CADA mensaje entrante
// del cliente, que es justo lo que la abre. Fuera de WhatsApp no significa nada
// y se deja como estaba en vez de inventar una fecha.
const _ventana_hasta = inp.canal === 'whatsapp'
  ? new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
  : (row ? (row.ventana_hasta || null) : null);
const prevState = (row && row.state && typeof row.state === 'object') ? row.state : {};
const prevPhone = prevState.contact_phone || null;
const prevPendingAppt = prevState.pending_appointment_id || null;
const prevPendingApptSvc = prevState.pending_appointment_service_id || null;
const prevPendingSvc = prevState.pending_service_id || null;
const prevLastAppt = prevState.last_appointment_id || null;
const prevAwaitingSlots = prevState.awaiting_slots_offer === true;
const prevAltSlotsDate = prevState.alt_slots_date || null;
const prevAltSlotsTime = prevState.alt_slots_time || null;
const prevBulkConfirm = prevState.awaiting_bulk_confirm === true;
const prevBulkIds = prevState.bulk_appointment_ids || '';
const prevShownIds = prevState.shown_appointment_ids || '';
// Slots del flujo en curso (servicio/día/hora/franja). Se reinyectan para que el bloque
// CONTEXTO del prompt del Core no diga "null" en cada turno: eso hacía que el LLM
// olvidara alternativamente el servicio o el día y la conversación entrara en bucle.
const prevSlotServiceQuery = prevState.slot_service_query || null;
const prevSlotDate = prevState.slot_date || null;
const prevSlotTime = prevState.slot_time || null;
const prevSlotDaypart = prevState.slot_daypart || null;
// WhatsApp reintrega el mismo mensaje si tardamos en responder: se descarta por id.
const prevMsgId = prevState.last_client_message_id || null;
const _duplicate = !!(inp.client_message_id && prevMsgId && inp.client_message_id === prevMsgId);
// aviso de privacidad: una vez por sesión (si la fila caduca/se borra, se vuelve a mostrar)
const _show_privacy = prevState.privacy_notice_shown !== true;

// rate-limit por session_key (state.rl)
const now = Date.now();
let rl = (prevState.rl && typeof prevState.rl === 'object') ? { ...prevState.rl } : { count: 0, window_start: now };
if (now - (rl.window_start || 0) > (inp.rl_window_ms || 300000)) rl = { count: 0, window_start: now };
rl.count = (rl.count || 0) + 1;
const _rate_limited = rl.count > (inp.rl_max || 20);

// identidad conocida del hilo: la del canal si la hay, si no la que ya teníamos
const known_phone = inp.from_phone || prevPhone || null;
const state_next = { ...prevState, rl, contact_phone: known_phone,
  last_client_message_id: inp.client_message_id || prevMsgId,
  privacy_notice_shown: true };

return [{ json: {
  ...inp,
  _session_id: row ? row.id : null,
  // Lo que ya tenía la sesión manda; si no tenía, lo que acaba de resolverse.
  // Así una conversación que empieza con un desconocido queda atada al contacto
  // en cuanto exista, sin que nadie lo asocie a mano.
  _prev_contact_id: (row && row.contact_id) || _contacto_resuelto || null,
  _prev_flujo_activo: row ? (row.flujo_activo || null) : null,
  _known_phone: known_phone,
  _prev_pending_appt: prevPendingAppt,
  _prev_pending_appt_svc: prevPendingApptSvc,
  _prev_pending_svc: prevPendingSvc,
  _prev_last_appt: prevLastAppt,
  _rate_limited, _duplicate, _show_privacy, state_next,
  _modo, _relevo, _ventana_hasta,
  core_in: {
    message: inp.message, sessionID: inp.session_key, client_id: inp.tenant, canal: inp.canal,
    flujo_activo: row ? (row.flujo_activo || null) : null,
    contact_phone: known_phone,
    contact_name: inp.from_name,
    pending_appointment_id: prevPendingAppt,
    pending_appointment_service_id: prevPendingApptSvc,
    pending_service_id: prevPendingSvc,
    last_appointment_id: prevLastAppt,
    offered_alt_slots: prevAwaitingSlots,
    offered_alt_slots_date: prevAltSlotsDate,
    offered_alt_slots_time: prevAltSlotsTime,
    awaiting_bulk_confirm: prevBulkConfirm,
    bulk_appointment_ids: prevBulkIds,
    shown_appointment_ids: prevShownIds,
    service_query: prevSlotServiceQuery,
    date: prevSlotDate,
    time: prevSlotTime,
    daypart: prevSlotDaypart,
    booking_base_url: inp.booking_base_url, directus_base_url: inp.directus_base_url,
    tenant_timezone: inp.tenant_timezone,
  },
} }];

const c = $json;
const core_reply = 'Estás enviando mensajes muy seguidos. Espera unos minutos y sigo contigo.';
const privacy_prompt = c._show_privacy
  ? { intro: c.privacy_intro, url: c.privacy_policy_url, label: c.privacy_button_label }
  : null;
const reply_to_user = privacy_prompt
  ? `${privacy_prompt.intro}\n\nPuedes leer los detalles en nuestra política de privacidad: ${privacy_prompt.url}\n\n${core_reply}`
  : core_reply;
return [{ json: {
  _session_id: c._session_id, session_key: c.session_key, canal: c.canal,
  reply_to: c.reply_to, directus_base_url: c.directus_base_url,
  save: { session_key: c.session_key, canal: c.canal, contact_id: c._prev_contact_id,
          flujo_activo: c._prev_flujo_activo, ventana_hasta: c._ventana_hasta,
          state: c.state_next },
  ok: false, intent: c._prev_flujo_activo || null,
  reply_to_user, core_reply, privacy_prompt,
  needs_user_reply: true,
} }];

const ctx = $('Code · Preparar contexto').item.json;
const inp = $('Code · Validar entrada').item.json;
const out = $json ?? {};
const contact_id = out.contact_id || ctx._prev_contact_id || null;
const contact_phone = out.contact_phone || ctx._known_phone || null;
const flujo_activo = out.flujo_activo ?? null;
const pending_appointment_id = flujo_activo
  ? (out.pending_appointment_id || ctx._prev_pending_appt || null)
  : null;
const pending_appointment_service_id = flujo_activo
  ? (out.pending_appointment_service_id || ctx._prev_pending_appt_svc || null)
  : null;
const pending_service_id = flujo_activo
  ? (out.pending_service_id || ctx._prev_pending_svc || null)
  : null;
const last_appointment_id = out.last_appointment_id || ctx._prev_last_appt || null;
const awaiting_slots_offer = out.awaiting_slots_offer === true;
const alt_slots_date = out.awaiting_slots_offer === true ? (out.alt_slots_date || null) : null;
const alt_slots_time = out.awaiting_slots_offer === true ? (out.alt_slots_time || null) : null;
const awaiting_bulk_confirm = out.awaiting_bulk_confirm === true;
const bulk_appointment_ids = awaiting_bulk_confirm ? (out.bulk_appointment_ids || '') : '';
const shown_appointment_ids = out.shown_appointment_ids || '';
// Mismo ciclo de vida que pending_service_id: viven mientras el flujo siga abierto y se
// limpian solos en cuanto flujo_activo vuelve a null (operación terminada o cambio de tema).
const slot_service_query = flujo_activo ? (out.slot_service_query || null) : null;
const slot_date = flujo_activo ? (out.slot_date || null) : null;
const slot_time = flujo_activo ? (out.slot_time || null) : null;
const slot_daypart = flujo_activo ? (out.slot_daypart || null) : null;

// Aviso de privacidad: una vez por sesión. Si el mensaje base es el saludo genérico
// (intent null), no lo repetimos detrás del aviso -- sería un "hola" duplicado.
const _isGenericGreeting = (out.intent === null || out.intent === undefined);
const core_reply = (ctx._show_privacy && _isGenericGreeting) ? '' : (out.reply_to_user || '');
const privacy_prompt = ctx._show_privacy
  ? { intro: ctx.privacy_intro, url: ctx.privacy_policy_url, label: ctx.privacy_button_label }
  : null;
// reply_to_user combinado en texto plano (webchat y cualquier canal sin botones nativos);
// WhatsApp usa privacy_prompt + core_reply por separado para el botón CTA-URL.
const reply_to_user = privacy_prompt
  ? [
      `${privacy_prompt.intro}\n\nPuedes leer los detalles en nuestra política de privacidad: ${privacy_prompt.url}`,
      core_reply,
    ].filter(Boolean).join('\n\n')
  : core_reply;

return [{ json: {
  _session_id: ctx._session_id, session_key: inp.session_key, canal: inp.canal,
  reply_to: inp.reply_to, directus_base_url: inp.directus_base_url,
  save: { session_key: inp.session_key, canal: inp.canal, contact_id,
          flujo_activo,
          ventana_hasta: ctx._ventana_hasta,
          state: { ...ctx.state_next, contact_phone, pending_service_id,
                   pending_appointment_id, pending_appointment_service_id,
                   last_appointment_id, awaiting_slots_offer, alt_slots_date, alt_slots_time,
                   awaiting_bulk_confirm, bulk_appointment_ids, shown_appointment_ids,
                   slot_service_query, slot_date, slot_time, slot_daypart } },
  ok: out.ok !== false, intent: out.intent ?? null,
  reply_to_user, core_reply, privacy_prompt,
  needs_user_reply: out.needs_user_reply === true,
} }];

const f = $('Code · Fusionar resultado').isExecuted
  ? $('Code · Fusionar resultado').item.json
  : $('Code · Salida relevo humano').isExecuted
    ? $('Code · Salida relevo humano').item.json
    : $('Code · Salida rate limit').item.json;
// El estado del guardado de sesión ya no llega en $json: lo recoge Preparar mensajes,
// que es quien lee ahora la respuesta del PATCH/POST.
const p = $('Code · Preparar mensajes').item.json;
const s = (p && p._sesion) || {};
if ((s.status ?? 0) >= 300 || s.errores) {
  console.log('Entry: fallo al guardar conversation_sessions ' + (s.status ?? 0) + ': ' + (s.errores || ''));
}
// Y el de los mensajes, que es informativo: no registrarlos no rompe la conversación.
if ($('HTTP · Guardar mensajes').isExecuted) {
  const m = $('HTTP · Guardar mensajes').item.json ?? {};
  const mc = m.statusCode ?? 0;
  if (mc >= 300 || (m.body && m.body.errors)) {
    console.log('Entry: fallo al guardar conversation_messages ' + mc + ': ' + JSON.stringify((m.body && m.body.errors) || m.body || {}));
  }
}
return [{ json: {
  ok: f.ok, intent: f.intent, reply: f.reply_to_user, needs_user_reply: f.needs_user_reply,
  core_reply: f.core_reply ?? f.reply_to_user, privacy_prompt: f.privacy_prompt || null,
  session_key: f.session_key, canal: f.canal, to: f.reply_to || {},
} }];

const inp = $('Code · Validar entrada').item.json;
// Reentrega del mismo mensaje: ni Core ni respuesta. El adapter no envía nada.
return [{ json: { ok: true, intent: null, reply: '', core_reply: '', privacy_prompt: null,
  needs_user_reply: false, session_key: inp.session_key, canal: inp.canal,
  to: inp.reply_to || {}, duplicate: true } }];

// Deja constancia del turno en conversation_messages: lo que escribió el cliente y
// lo que contestó Lucía. Es lo que el gestor lee, y la base sobre la que se monta
// el relevo humano.
//
// REGLA: esto NUNCA puede tumbar una conversación. Si algo aquí falla o falta, se
// registra menos y ya está -- el cliente recibe su respuesta igual. Por eso no hay
// throw en todo el nodo y por eso el HTTP de después lleva neverError.
const inp = $('Code · Validar entrada').item.json;
// Tres orígenes posibles, no dos: el turno normal, el corte por rate limit y el
// relevo humano. Encadenar con isExecuted y no con un ternario simple importa --
// pedir .item.json de una rama que no corrió lanza.
const f = $('Code · Fusionar resultado').isExecuted
  ? $('Code · Fusionar resultado').item.json
  : $('Code · Salida relevo humano').isExecuted
    ? $('Code · Salida relevo humano').item.json
    : $('Code · Salida rate limit').item.json;

// Respuesta del guardado de sesión (fullResponse), que hasta ahora leía Salida Entry.
const r = $json ?? {};
const sesion = {
  status: r.statusCode ?? 0,
  errores: (r.body && r.body.errors) ? JSON.stringify(r.body.errors) : null,
};

// El id de la sesión: en un PATCH ya lo teníamos; en un POST solo lo sabemos ahora.
const session_id =
  (f && f._session_id) ||
  (r.body && r.body.data && r.body.data.id) ||
  null;

const canal = inp.canal || f.canal || null;
const contact_id = (f && f.save && f.save.contact_id) || null;

const entrante = (inp.message || '').toString().trim();

// Se guarda lo que el canal ENTREGA, no el texto combinado de v1 -- que no lo recibe
// nadie tal cual. El aviso de privacidad viaja siempre como mensaje propio: en WhatsApp
// es un CTA-url aparte y en webchat lo pinta el widget al abrir. Concatenado aquí, el
// gestor leería un mensaje que el cliente nunca vio de esa forma.
const aviso = (f && f.privacy_prompt && f.privacy_prompt.intro)
  ? `${f.privacy_prompt.intro}\n\n${f.privacy_prompt.url || ''}`.trim()
  : '';
// core_reply es la respuesta de Lucía. Solo se cae a reply_to_user cuando NO hay aviso:
// si lo hay y core_reply viene vacía, es que el saludo genérico se suprimió a propósito
// detrás del aviso y el turno entero es el aviso -- una fila, no dos.
const respuesta = ((f && f.core_reply) || '').toString().trim()
  || (aviso ? '' : ((f && f.reply_to_user) || '').toString().trim());

const filas = [];

// Sin sesión no hay a qué colgar el mensaje (session_id es NOT NULL en la práctica:
// es la columna que agrupa el hilo). Se prefiere no registrar a registrar suelto.
if (session_id) {
  if (entrante) {
    filas.push({
      session_id, contact_id, canal,
      direccion: 'entrante',
      autor: 'cliente',
      texto: entrante,
      estado_envio: 'recibido',
      canal_message_id: inp.client_message_id || null,
    });
  }
  // Una fila por mensaje realmente entregado, en el orden en que salen.
  // 'lucia' incluso para el aviso o para el corte por rate limit: lo emite el sistema.
  // 'humano' queda reservado para lo que escribe una persona del negocio.
  for (const texto of [aviso, respuesta]) {
    if (!texto) continue;
    filas.push({
      session_id, contact_id, canal,
      direccion: 'saliente',
      autor: 'lucia',
      texto,
      estado_envio: 'enviado',
      canal_message_id: null,
    });
  }
}

return [{ json: {
  directus_base_url: inp.directus_base_url,
  _sesion: sesion,
  _hay_mensajes: filas.length > 0,
  filas,
} }];

// El hilo lo lleva una persona: Lucía no contesta. El mensaje del cliente SÍ se
// registra -- es justo lo que el gestor necesita ver -- y por eso esta rama pasa
// igualmente por el guardado de sesión y de mensajes, como la de rate limit.
//
// Sin texto de salida: el adapter de WhatsApp ya no envía nada cuando el texto
// viene vacío (`if (texto)` en Code · Preparar envío). No se manda un "ahora te
// atiende una persona" automático: si el gestor ha cogido el hilo, el siguiente
// mensaje que reciba el cliente tiene que ser suyo, no otro robot.
// El gestor de memoria va justo antes y su salida NO es el contexto, así que
// este se busca por nombre en vez de leer $json.
const c = $('Code · Preparar contexto').item.json;
// El aviso de privacidad sí sale si tocaba: es una obligación legal, no una
// respuesta de Lucía. En la práctica no pasa (una sesión nueva no puede estar
// en 'humano' todavía), pero si pasara, callarlo sería lo incorrecto.
const privacy_prompt = c._show_privacy
  ? { intro: c.privacy_intro, url: c.privacy_policy_url, label: c.privacy_button_label }
  : null;
return [{ json: {
  _session_id: c._session_id, session_key: c.session_key, canal: c.canal,
  reply_to: c.reply_to, directus_base_url: c.directus_base_url,
  save: { session_key: c.session_key, canal: c.canal, contact_id: c._prev_contact_id,
          flujo_activo: c._prev_flujo_activo, ventana_hasta: c._ventana_hasta,
          state: c.state_next },
  ok: true, intent: null,
  reply_to_user: '', core_reply: '', privacy_prompt,
  needs_user_reply: false,
  modo: 'humano',
} }];
